export function onInput(inputs, context) {
    console.log("onInput");
    console.log("inputs[0]="+inputs[0].value)
    // input[0] = base64 string
    const bin = Base64.decode(inputs[0].value);

    if (bin.length < 40) {
        // 10 float32 values expected
        return [];
    }

    console.log("Create Dataview");
    const dv = new DataView(bin.buffer);
    const values = [];
    for (let i = 0; i < 10; i++) {
        values.push(dv.getFloat32(i * 4, false));
    }
    console.log("Get temp and torque");

    // Prepare outputs for ONNX and second JS
    const temp = values[8];
    const torque = values[9];
    console.log("Returning values: "+JSON.stringify([values]));

    return [
        JSON.stringify([values]), // out0 → ONNX input
        temp,                   // out1
        torque,                 // out2
    ];
}

export function onInput(inputs, context) {
    const raw = String(inputs[0].value || "[]");
    const temp = Number(inputs[1].value || 0);
    const torque = Number(inputs[2].value || 0);
    const cls = Number(inputs[3].value || 0);
    const conf = Number(inputs[4].value || 0);

    const labelMap = {
        0: "normal",
        1: "early_bearing_wear",
        2: "gear_tooth_damage",
        3: "misalignment"
    };

    const label = labelMap[cls] || "unknown";

    const good = (cls === 0);

    if (good) {
        return [temp, torque, good];
    }

    // Construct LLM prompt
    const prompt = `
Wind turbine gearbox anomaly detected.
Model classification: ${label}
Confidence: ${conf.toFixed(3)}
Raw features: ${raw}
Temperature: ${temp}
Torque: ${torque}

Provide a likely root cause, probable secondary effects, and clear recommended diagnostic steps for a field engineer.
    `.trim();

    return [temp, torque, good, prompt];
}
